import torch
import torch.nn as nn

# PTX source for fp16 matrix multiplication (M,N <= 256, K large)
PTX_SOURCE = r"""
.version 7.2
.target sm_80
.address_size 64

.visible .entry matmul_fp16(
    .param .u64 A,
    .param .u64 B,
    .param .u64 C,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // pointers
    .reg .u64 %A_ptr, %B_ptr, %C_ptr;
    ld.param.u64 %A_ptr, [A];
    ld.param.u64 %B_ptr, [B];
    ld.param.u64 %C_ptr, [C];

    // dimensions
    .reg .u32 %M, %N, %K;
    ld.param.u32 %M, [M];
    ld.param.u32 %N, [N];
    ld.param.u32 %K, [K];

    // thread indices
    .reg .u32 %tid_x, %tid_y, %bid_x, %bid_y;
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %bid_x, %ctaid.x;
    mov.u32 %bid_y, %ctaid.y;

    // compute global row and col (16×16 tile)
    .reg .u32 %row, %col;
    mad.lo.u32 %col, %bid_x, 16, %tid_x;
    mad.lo.u32 %row, %bid_y, 16, %tid_y;

    // boundary check
    .reg .pred %p_out;
    setp.ge.u32 %p_out, %row, %M;
    @%p_out bra DONE;
    setp.ge.u32 %p_out, %col, %N;
    @%p_out bra DONE;

    // accumulator in fp32
    .reg .f32 %sum;
    mov.f32 %sum, 0f00000000;

    // loop variable i
    .reg .u32 %i;
    mov.u32 %i, 0;

LOOP:
    setp.ge.u32 %p_out, %i, %K;
    @%p_out bra DONE_LOOP;

    // ---- load A[row, i] ----
    // offset = ((row * K) + i) * 2
    .reg .u64 %offsetA, %rowK, %elemA;
    mul.wide.u32 %rowK, %row, %K;          // row*K (elements)
    add.u64 %elemA, %rowK, %i;            // element index
    mul.wide.u32 %offsetA, %elemA, 2;     // bytes
    .reg .f16 %a_val;
    ld.global.nc.f16 %a_val, [%A_ptr + %offsetA];

    // ---- load B[i, col] ----
    // offset = ((i * N) + col) * 2
    .reg .u64 %offsetB, %iN, %elemB;
    mul.wide.u32 %iN, %i, %N;              // i*N (elements)
    add.u64 %elemB, %iN, %col;            // element index
    mul.wide.u32 %offsetB, %elemB, 2;     // bytes
    .reg .f16 %b_val;
    ld.global.nc.f16 %b_val, [%B_ptr + %offsetB];

    // convert to fp32
    .reg .f32 %a_f, %b_f;
    cvt.rn.f32.f16 %a_f, %a_val;
    cvt.rn.f32.f16 %b_f, %b_val;

    // FMA
    fma.rn.f32 %sum, %a_f, %b_f, %sum;

    // i++
    add.u32 %i, %i, 1;
    bra LOOP;

DONE_LOOP:

    // write result C[row, col]
    // offset = ((row * N) + col) * 2
    .reg .u64 %offsetC, %rowN, %elemC;
    mul.wide.u32 %rowN, %row, %N;
    add.u64 %elemC, %rowN, %col;
    mul.wide.u32 %offsetC, %elemC, 2;

    // convert sum to fp16
    .reg .f16 %c_val;
    cvt.rn.f16.f32 %c_val, %sum;

    st.global.nc.f16 [%C_ptr + %offsetC], %c_val;

DONE:
    ret;
}
"""

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions must match"
        C = torch.empty(M, N, dtype=torch.float16, device='cuda')
        grid_x = (N + 15) // 16
        grid_y = (M + 15) // 16
        block = (16, 16, 1)
        args = [A.data_ptr(), B.data_ptr(), C.data_ptr(), M, N, K]
        ptx_launch(self.module, "matmul_fp16", (grid_x, grid_y, 1), block, args)
        return C
